const { test, expect } = require('@playwright/test');

// CodeAgent terminal-state hook (frontend_recipe.build_terminal_state_hook)
// CodeAgent#751: once this proof's own assertions pass, nothing on the page may still
// show a loading placeholder. A render path that never reaches its terminal state
// (data, an empty note, an error) is a defect the proof did not ask about. Elements
// under [data-loading-ok] are exempt. Generated by the engine at write time -- edit
// the generator, not this block.
test.afterEach(async ({ page }, testInfo) => {
  if (testInfo.status !== testInfo.expectedStatus || page.isClosed()) return;
  const stuck = await page.evaluate((markers) => Array.from(document.querySelectorAll('body *')).filter((el) => {
    if (el.children.length || el.closest('[data-loading-ok]')) return false;
    const t = (el.textContent || '').trim();
    if (!t || !markers.some((m) => t === m || t.startsWith(m))) return false;
    const r = el.getBoundingClientRect();
    return r.width > 0 && r.height > 0;
  }).map((el) => {
    const p = el.closest('[data-panel]');
    const cls = (el.getAttribute('class') || '').trim().split(/\s+/)[0];
    return (p && p.getAttribute('data-panel')) || (el.tagName.toLowerCase() + (cls ? '.' + cls : ''));
  }), ["Loading data\u2026", "Loading data...", "Loading\u2026", "Loading..."]).catch(() => []);
  test.expect(stuck, `element(s) still showing a loading placeholder after the proof: ${stuck.join(', ')} -- every render path must reach a terminal state (data, an empty note or an error), or declare data-loading-ok`).toEqual([]);
});


test('issue249 surgical', async ({ page }) => {
  await page.route('**/api/**', (route) => {
    const url = route.request().url();
    if (url.includes('/api/auth/config')) {
      return route.fulfill({ json: { authEnabled: true, authMode: 'development' } });
    }
    if (url.includes('/api/auth/me')) {
      return route.fulfill({ json: { authenticated: true, user: { sub: 'dev', username: 'dev', email: null, roles: ['user'], groups: [], raw_claims: {} } } });
    }
    if (url.includes('/api/decisions/summary')) {
      return route.fulfill({ json: { pending: 3, decided: 10, total: 13 } });
    }
    if (url.includes('/api/drift')) {
      return route.fulfill({ json: { items: [] } });
    }
    if (url.includes('/api/excess')) {
      return route.fulfill({ json: { items: [] } });
    }
    if (url.includes('/api/stockout')) {
      return route.fulfill({ json: { items: [] } });
    }
    return route.fulfill({ json: {} });
  });

  // --- Narrow viewport: 390 x 844 ---
  await page.setViewportSize({ width: 390, height: 844 });
  await page.goto('/');

  // Sign in through the development token card
  await page.waitForSelector('#auth #signin-button', { state: 'visible' });
  const input = page.locator('#auth input');
  if (await input.count() > 0) {
    await input.first().fill('dev');
  }
  await page.locator('#auth #signin-button').click();

  // Wait for the overview tiles and cards to render
  await page.waitForSelector('.ov-tiles .ov-tile', { state: 'visible' });
  await page.waitForSelector('.ov-cards .ov-card', { state: 'visible' });

  // Three tiles share a left edge and stack top to bottom
  const tiles = page.locator('.ov-tile');
  expect(await tiles.count()).toBe(3);
  const tileBoxes = [];
  for (let i = 0; i < 3; i++) {
    tileBoxes.push(await tiles.nth(i).boundingBox());
  }
  expect(tileBoxes[1].x).toBe(tileBoxes[0].x);
  expect(tileBoxes[2].x).toBe(tileBoxes[0].x);
  expect(tileBoxes[1].y).toBeGreaterThan(tileBoxes[0].y);
  expect(tileBoxes[2].y).toBeGreaterThan(tileBoxes[1].y);

  // Three cards share a left edge and stack top to bottom
  const cards = page.locator('.ov-card');
  expect(await cards.count()).toBe(3);
  const cardBoxes = [];
  for (let i = 0; i < 3; i++) {
    cardBoxes.push(await cards.nth(i).boundingBox());
  }
  expect(cardBoxes[1].x).toBe(cardBoxes[0].x);
  expect(cardBoxes[2].x).toBe(cardBoxes[0].x);
  expect(cardBoxes[1].y).toBeGreaterThan(cardBoxes[0].y);
  expect(cardBoxes[2].y).toBeGreaterThan(cardBoxes[1].y);

  // No value is clipped: scrollWidth <= clientWidth
  const noClip = await page.evaluate(() => {
    const els = document.querySelectorAll('.ov-tile-value, .ov-figure-value');
    for (const el of els) {
      if (el.scrollWidth > el.clientWidth) return false;
    }
    return true;
  });
  expect(noClip).toBe(true);

  // No horizontal scroll
  const docScrollWidth = await page.evaluate(() => document.documentElement.scrollWidth);
  expect(docScrollWidth).toBeLessThanOrEqual(390);

  // --- Wide viewport: 1440 x 900 ---
  await page.setViewportSize({ width: 1440, height: 900 });
  await page.waitForTimeout(150);

  // Three tiles share one top edge (side by side)
  const tileBoxesWide = [];
  for (let i = 0; i < 3; i++) {
    tileBoxesWide.push(await tiles.nth(i).boundingBox());
  }
  expect(tileBoxesWide[1].y).toBe(tileBoxesWide[0].y);
  expect(tileBoxesWide[2].y).toBe(tileBoxesWide[0].y);
});
